//! A writer, NOT a general C14N implementation. Every emitted element has an
//! explicit end tag, only the root uses a namespace, text is C14N-escaped, and
//! there are no comments, PIs, DTDs, inherited xml:* attributes or default NSs.
//! Consequently these generated bytes equal Exclusive C14N 1.0. Never feed an
//! arbitrary XML document to this signer. SOAP is added AFTER signing the record.
use crate::{vero_filing::VeroCredentials, AdapterError, CredentialHandle};
use aggountant_domain::{validate_hetu, TravelLine, WageReport};
use base64::{engine::general_purpose::STANDARD, Engine};
use chrono::{DateTime, Utc};
use ring::{rand::SystemRandom, signature};
use sha2::{Digest, Sha256};
use x509_parser::{parse_x509_certificate, pem::parse_x509_pem};

const DS: &str = "http://www.w3.org/2000/09/xmldsig#";
const C14N: &str = "http://www.w3.org/2001/10/xml-exc-c14n#";
pub const WAGE_NS: &str = "http://www.tulorekisteri.fi/2017/1/WageReportsToIR";
pub const STATUS_NS: &str = "http://www.tulorekisteri.fi/2017/1/StatusRequestToIR";
fn bad() -> AdapterError {
    AdapterError::Malformed("invalid Tulorekisteri signing material or record".into())
}
fn text(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('\r', "&#xD;")
}
fn e(name: &str, s: &str) -> String {
    format!("<{name}>{}</{name}>", text(s))
}
fn id(kind: &str, code: &str) -> String {
    format!("<Id>{}{}</Id>", e("Type", kind), e("Code", code))
}
fn actors(business_id: &str) -> String {
    [
        "DeliveryDataOwner",
        "DeliveryDataCreator",
        "DeliveryDataSender",
    ]
    .iter()
    .map(|n| format!("<{n}>{}{}</{n}>", e("Type", "1"), e("Code", business_id)))
    .collect()
}
/// Offline, no credential required. HETU never appears in an error or preview.
pub fn wage_record(
    report: &WageReport,
    hetu: &str,
    timestamp: DateTime<Utc>,
) -> Result<String, AdapterError> {
    report.validate(timestamp.date_naive()).map_err(|_| bad())?;
    validate_hetu(hetu)
        .map_err(|_| AdapterError::Malformed("invalid income earner HETU in PII store".into()))?;
    let mut data = e("Timestamp", &timestamp.to_rfc3339());
    data += &e("Source", "aggountant");
    data += &e("DeliveryDataType", "100");
    data += &e("DeliveryId", &report.delivery_id());
    data += &e("FaultyControl", "2");
    data += &e("ProductionEnvironment", "true");
    data += &actors(report.business_id.as_str());
    data += &format!(
        "<PaymentPeriod>{}{}{}</PaymentPeriod>",
        e("PaymentDate", &report.payment_date.to_string()),
        e("StartDate", &report.period_start.to_string()),
        e("EndDate", &report.period_end.to_string())
    );
    data += &format!(
        "<ContactPersons><ContactPerson>{}{}</ContactPerson></ContactPersons>",
        e("Name", report.contact_name.as_str()),
        e("Telephone", report.contact_phone.as_str())
    );
    data += &format!(
        "<Payer><PayerIds>{}</PayerIds></Payer>",
        id("1", report.business_id.as_str())
    );
    data += &format!("<Reports><Report><ReportData>{}{}</ReportData><IncomeEarner><IncomeEarnerIds>{}</IncomeEarnerIds>",e("ActionCode","1"),e("ReportId",&report.report_id()), id("2",hetu));
    if report.joint_owner {
        data += "<IncomeEarnerOther><IncomeEarnerTypes><IncomeEarnerType>2</IncomeEarnerType></IncomeEarnerTypes></IncomeEarnerOther>";
    }
    data += "</IncomeEarner><Transactions>";
    for line in &report.lines {
        data += &format!(
            "<Transaction><TransactionBasic>{}{}</TransactionBasic>",
            e("TransactionCode", line.code()),
            e("Amount", &line.amount())
        );
        data += &match line {
            TravelLine::Kilometres { kilometers, .. } => format!(
                "<KmAllowance>{}</KmAllowance>",
                e("Kilometers", &kilometers.to_string())
            ),
            TravelLine::DailyAllowance { allowance_code, .. } => format!(
                "<DailyAllowance>{}</DailyAllowance>",
                e("AllowanceCode", &allowance_code.to_string())
            ),
        };
        data += "</Transaction>";
    }
    data += "</Transactions></Report></Reports>";
    Ok(format!("<ir:WageReportRequestToIR xmlns:ir=\"{WAGE_NS}\"><DeliveryData>{data}</DeliveryData></ir:WageReportRequestToIR>"))
}
pub fn status_record(report: &WageReport, timestamp: DateTime<Utc>) -> String {
    format!(
        "<ir:StatusRequestToIR xmlns:ir=\"{STATUS_NS}\">{}{}{}{}{}</ir:StatusRequestToIR>",
        e("Timestamp", &timestamp.to_rfc3339()),
        e("DeliveryDataType", "100"),
        e("DeliveryId", &report.delivery_id()),
        e("ProductionEnvironment", "true"),
        actors(report.business_id.as_str())
    )
}
fn signed_info(digest: &str) -> String {
    format!("<ds:SignedInfo xmlns:ds=\"{DS}\"><ds:CanonicalizationMethod Algorithm=\"{C14N}\"></ds:CanonicalizationMethod><ds:SignatureMethod Algorithm=\"http://www.w3.org/2001/04/xmldsig-more#rsa-sha256\"></ds:SignatureMethod><ds:Reference URI=\"\"><ds:Transforms><ds:Transform Algorithm=\"{DS}enveloped-signature\"></ds:Transform><ds:Transform Algorithm=\"{C14N}\"></ds:Transform></ds:Transforms><ds:DigestMethod Algorithm=\"http://www.w3.org/2001/04/xmlenc#sha256\"></ds:DigestMethod><ds:DigestValue>{digest}</ds:DigestValue></ds:Reference></ds:SignedInfo>")
}
/// Called only on this module's generated records. The adapter reconstructs them
/// from validated input, rather than signing caller-supplied XML.
pub(crate) fn sign_record(record: &str, handle: &CredentialHandle) -> Result<String, AdapterError> {
    let credentials = VeroCredentials::parse(handle.expose_secret()).map_err(|_| bad())?;
    let key_pem = &credentials.client_private_key_pem;
    let (label, pkcs8) = if key_pem.starts_with("-----BEGIN PRIVATE KEY-----") {
        ("PRIVATE KEY", true)
    } else {
        ("RSA PRIVATE KEY", false)
    };
    let base64 = key_pem
        .strip_prefix(&format!("-----BEGIN {label}-----"))
        .and_then(|s| s.trim().strip_suffix(&format!("-----END {label}-----")))
        .ok_or_else(bad)?;
    let key_der = STANDARD
        .decode(
            base64
                .chars()
                .filter(|c| !c.is_ascii_whitespace())
                .collect::<String>(),
        )
        .map_err(|_| bad())?;
    let key = if pkcs8 {
        signature::RsaKeyPair::from_pkcs8(&key_der)
    } else {
        signature::RsaKeyPair::from_der(&key_der)
    }
    .map_err(|_| bad())?;
    let (_, cert) =
        parse_x509_pem(credentials.client_certificate_pem.as_bytes()).map_err(|_| bad())?;
    let (_, parsed) = parse_x509_certificate(&cert.contents).map_err(|_| bad())?;
    let info = signed_info(&STANDARD.encode(Sha256::digest(record.as_bytes())));
    let mut sig = vec![0; key.public().modulus_len()];
    key.sign(
        &signature::RSA_PKCS1_SHA256,
        &SystemRandom::new(),
        info.as_bytes(),
        &mut sig,
    )
    .map_err(|_| bad())?;
    // Fail closed for mismatched certificate/key, not just a syntactically valid key.
    signature::UnparsedPublicKey::new(
        &signature::RSA_PKCS1_2048_8192_SHA256,
        parsed.public_key().subject_public_key.data.as_ref(),
    )
    .verify(info.as_bytes(), &sig)
    .map_err(|_| bad())?;
    let signature = format!("<ds:Signature xmlns:ds=\"{DS}\">{}<ds:SignatureValue>{}</ds:SignatureValue><ds:KeyInfo><ds:X509Data><ds:X509Certificate>{}</ds:X509Certificate></ds:X509Data></ds:KeyInfo></ds:Signature>",info.replace(&format!(" xmlns:ds=\"{DS}\""),""),STANDARD.encode(sig),STANDARD.encode(&cert.contents));
    let end = record.rfind("</ir:").ok_or_else(bad)?;
    Ok(format!("{}{}{}", &record[..end], signature, &record[end..]))
}
pub fn record_hash(record: &str) -> String {
    hex::encode(Sha256::digest(record.as_bytes()))
}
pub fn soap(record: &str) -> String {
    format!("<soap:Envelope xmlns:soap=\"http://schemas.xmlsoap.org/soap/envelope/\"><soap:Body>{record}</soap:Body></soap:Envelope>")
}
